        <h1 id="cars">Cars</h1>

    

                                <h2 id="cars-GETapi-v1-cars">List cars</h2>

<p>
</p>



<span id="example-requests-GETapi-v1-cars">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request GET \
    --get "http://localhost/api/v1/cars?per_page=15&amp;q=%22abc123%22&amp;filter%5Bcompany_id%5D=4&amp;filter%5Buser_id%5D=2" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json"</code></pre></div>


<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost/api/v1/cars"
);

const params = {
    "per_page": "15",
    "q": ""abc123"",
    "filter[company_id]": "4",
    "filter[user_id]": "2",
};
Object.keys(params)
    .forEach(key =&gt; url.searchParams.append(key, params[key]));

const headers = {
    "Content-Type": "application/json",
    "Accept": "application/json",
};

fetch(url, {
    method: "GET",
    headers,
}).then(response =&gt; response.json());</code></pre></div>

</span>

<span id="example-responses-GETapi-v1-cars">
            <blockquote>
            <p>Example response (200):</p>
        </blockquote>
