                    <h2 id="endpoints-POSTapi-v1-procedures">POST /v1/procedures</h2>

<p>
</p>

<p>Creates procedure + writes prices for insurers 25/24/27 into procedure_company</p>

<span id="example-requests-POSTapi-v1-procedures">
<blockquote>Example request:</blockquote>


<div class="bash-example">
    <pre><code class="language-bash">curl --request POST \
    "http://localhost/api/v1/procedures" \
    --header "Content-Type: application/json" \
    --header "Accept: application/json" \
    --data "{
    \"code\": \"b\",
    \"description\": \"Et animi quos velit et fugiat.\",
    \"prices\": [
        {
            \"insurance_company_id\": 16,
            \"price\": 39
        }
    ]
}"
</code></pre></div>


<div class="javascript-example">
